effect.script:
function animate(env,el,param) {
let t = env.time;
let inTime = param.inTime / env.duration;
let outTime = param.outTime / env.duration;
if( t < inTime ) {
el.alpha *= EasingFunctions.easeInOutQuad(t/inTime)
}
if ( t > 1.0-outTime ) {
el.alpha *= EasingFunctions.easeInOutQuad((1.0-t)/outTime)
}
return el;
}
